            return _integrity()
        if prev_hash != crypto.AUDIT_GENESIS_PREV_HASH:
            return _integrity()
    elif checkpoint["event_hash"] != prev_hash:
        return _integrity()
    return {"ok": True, "checkpoint": checkpoint}

